    @Test
    public void testSerialization() throws IOException, ClassNotFoundException {
        CSVFormat original = CSVFormat.EXCEL.builder()
            .setHeader("a", "b")
            .setHeaderComments("comment")
            .setCommentMarker('#')
            .setNullString("NULL")
            .setQuoteMode(QuoteMode.ALL)
            .setMaxRows(10)
            .get();

        ByteArrayOutputStream bos = new ByteArrayOutputStream();
        try (ObjectOutputStream oos = new ObjectOutputStream(bos)) {
            oos.writeObject(original);
        }

        try (ObjectInputStream ois = new ObjectInputStream(new ByteArrayInputStream(bos.toByteArray()))) {
            CSVFormat deserialized = (CSVFormat) ois.readObject();
            assertEquals(original, deserialized);
            assertEquals(original.hashCode(), deserialized.hashCode());
            assertArrayEquals(original.getHeader(), deserialized.getHeader());
            assertArrayEquals(original.getHeaderComments(), deserialized.getHeaderComments());
            assertEquals(original.getCommentMarker(), deserialized.getCommentMarker());
            assertEquals(original.getNullString(), deserialized.getNullString());
            assertEquals(original.getQuoteMode(), deserialized.getQuoteMode());
            assertEquals(original.getMaxRows(), deserialized.getMaxRows());
        }
    }

    @Test
    public void testFormatMethod() throws IOException {
        CSVFormat format = CSVFormat.DEFAULT;
        String result = format.format("a", "b", "c");
        // DEFAULT uses RFC4180 with ignoreEmptyLines=true, recordSeparator=\r\n
        // format() prints a record without the trailing record separator
        assertEquals("a,b,c", result);
    }

