        String result = format.format("a", null, "c");
        assertEquals("a,NULL,c", result);
    }

    @Test
    public void testPrintAndParseRoundTrip() throws IOException {
        CSVFormat format = CSVFormat.DEFAULT.builder().setHeader("col1", "col2").get();
        StringWriter writer = new StringWriter();
        try (CSVPrinter printer = format.print(writer)) {
            printer.printRecord("value1", "value2");
        }
        String csv = writer.toString();
        // parse back
        try (CSVParser parser = CSVParser.parse(new StringReader(csv), format)) {
            assertTrue(parser.iterator().hasNext());
            CSVRecord record = parser.iterator().next();
            assertEquals("value1", record.get("col1"));
            assertEquals("value2", record.get("col2"));
            assertFalse(parser.iterator().hasNext());
        }
    }

    @Test
    public void testParseMethod() throws IOException {
        CSVFormat format = CSVFormat.DEFAULT;
        String csv = "a,b,c\n1,2,3\n";
        try (CSVParser parser = format.parse(new StringReader(csv))) {
            assertTrue(parser.iterator().hasNext());
            CSVRecord record = parser.iterator().next();
            assertEquals("a", record.get(0));
            assertEquals("b", record.get(1));
            assertEquals("c", record.get(2));
            assertTrue(parser.iterator().hasNext());
            record = parser.iterator().next();
            assertEquals("1", record.get(0));
            assertEquals("2", record.get(1));
            assertEquals("3", record.get(2));
            assertFalse(parser.iterator().hasNext());
        }
    }

    @Test
    public void testDeprecatedWithMethods() {
        CSVFormat format = CSVFormat.DEFAULT
            .withDelimiter(';')
            .withQuote('\'')
            .withEscape('\\')
            .withCommentMarker('#')
            .withRecordSeparator('\n')
            .withIgnoreEmptyLines(false)
            .withIgnoreHeaderCase(true)
            .withIgnoreSurroundingSpaces(true)
            .withNullString("NULL")
            .withQuoteMode(QuoteMode.ALL)
            .withHeader("a", "b")
            .withHeaderComments("comment")
            .withSkipHeaderRecord(true)
            .withAllowMissingColumnNames(true)
            .withAllowDuplicateHeaderNames(true)
            .withTrailingDelimiter(true)
            .withTrim(true)
            .withAutoFlush(true)
            .withSystemRecordSeparator();

        assertEquals(";", format.getDelimiterString());
        assertEquals('\'', format.getQuoteCharacter().charValue());
        assertEquals('\\', format.getEscapeCharacter().charValue());
        assertEquals('#', format.getCommentMarker().charValue());
        assertEquals("\n", format.getRecordSeparator());
        assertFalse(format.getIgnoreEmptyLines());
        assertTrue(format.getIgnoreHeaderCase());
        assertTrue(format.getIgnoreSurroundingSpaces());
        assertEquals("NULL", format.getNullString());
        assertEquals(QuoteMode.ALL, format.getQuoteMode());
        assertArrayEquals(new String[]{"a", "b"}, format.getHeader());
        assertArrayEquals(new String[]{"comment"}, format.getHeaderComments());
        assertTrue(format.getSkipHeaderRecord());
        assertTrue(format.getAllowMissingColumnNames());
        assertEquals(DuplicateHeaderMode.ALLOW_ALL, format.getDuplicateHeaderMode());
        assertTrue(format.getTrailingDelimiter());
        assertTrue(format.getTrim());
        assertTrue(format.getAutoFlush());
    }

