            .withRecordSeparator('\n')
            .withIgnoreEmptyLines(false)
            .withIgnoreHeaderCase(true)
            .withIgnoreSurroundingSpaces(true)
            .withNullString("NULL")
            .withQuoteMode(QuoteMode.ALL)
            .withHeader("a", "b")
            .withHeaderComments(" ")
            .withSkipHeaderRecord(true)
            .withAllowMissingColumnNames(true)
            .withAllowDuplicateHeaderNames(true)
            .withTrailingDelimiter(true)
            .withTrim(true)
            .withAutoFlush(true)
            .withSystemRecordSeparator();

        assertEquals(";", format.getDelimiterString());
        assertEquals('\'', format.getQuoteCharacter().charValue());
        assertEquals('\\', format.getEscapeCharacter().charValue());
        assertEquals('#', format.getCommentMarker().charValue());
        assertEquals("\n", format.getRecordSeparator());
        assertFalse(format.getIgnoreEmptyLines());
        assertTrue(format.getIgnoreHeaderCase());
        assertTrue(format.getIgnoreSurroundingSpaces());
        assertEquals("NULL", format.getNullString());
        assertEquals(QuoteMode.ALL, format.getQuoteMode());
        assertArrayEquals(new String[]{"a", "b"}, format.getHeader());
        assertArrayEquals(new String[]{" "}, format.getHeaderComments());
        assertTrue(format.getSkipHeaderRecord());
        assertTrue(format.getAllowMissingColumnNames());
        assertEquals(DuplicateHeaderMode.ALLOW_ALL, format.getDuplicateHeaderMode());
        assertTrue(format.getTrailingDelimiter());
        assertTrue(format.getTrim());
        assertTrue(format.getAutoFlush());
    }

