    @Test
    public void testParseStringWithDefaultFormat() throws IOException {
        final String csv = "a,b,c\n1,2,3\n4,5,6";
        try (CSVParser parser = CSVParser.parse(csv, CSVFormat.DEFAULT)) {
            final List<CSVRecord> records = parser.getRecords();
            assertEquals(2, records.size());
            assertArrayEquals(new String[]{"1", "2", "3"}, records.get(0).values());
            assertArrayEquals(new String[]{"4", "5", "6"}, records.get(1).values());
        }
    }

