    @Test
    public void testDuplicateHeaderModeAllowAll() throws IOException {
        final String csv = "a,a,b\n1,2,3";
        final CSVFormat format = CSVFormat.DEFAULT.withHeader("a", "a", "b").withDuplicateHeaderMode(DuplicateHeaderMode.ALLOW_ALL);
        try (CSVParser parser = CSVParser.parse(csv, format)) {
            final List<CSVRecord> records = parser.getRecords();
            assertEquals(1, records.size());
            // With ALLOW_ALL, last duplicate wins in map
            assertEquals("2", records.get(0).get("a"));
        }
    }

