    @Test
    public void testNullStringHandling() throws IOException {
        final String csv = "a,b\nNULL,2\n3,NULL";
        final CSVFormat format = CSVFormat.DEFAULT.withNullString("NULL");
        try (CSVParser parser = CSVParser.parse(csv, format)) {
            final List<CSVRecord> records = parser.getRecords();
            assertEquals(2, records.size());
            assertNull(records.get(0).get(0));
            assertEquals("2", records.get(0).get(1));
            assertEquals("3", records.get(1).get(0));
            assertNull(records.get(1).get(1));
        }
    }

    @Test
    public void testQuotedNullString() throws IOException {
        final String csv = "a,b\n\"NULL\",2\n3,\"NULL\"";
        final CSVFormat format = CSVFormat.DEFAULT.withNullString("NULL").withQuoteMode(QuoteMode.ALL_NON_NULL);
        try (CSVParser parser = CSVParser.parse(csv, format)) {
            final List<CSVRecord> records = parser.getRecords();
            assertEquals(2, records.size());
            // Quoted "NULL" should not be treated as null in ALL_NON_NULL mode
            assertEquals("NULL", records.get(0).get(0));
            assertEquals("NULL", records.get(1).get(1));
        }
    }

