    @Test
    public void testParseStringWithNullCharset() throws IOException {
        final String csv = "a,b\n1,2";
        try (CSVParser parser = CSVParser.parse(csv, (Charset) null, CSVFormat.DEFAULT)) {
            final List<CSVRecord> records = parser.getRecords();
            assertEquals(1, records.size());
        }
    }

    @Test
    public void testRecordNumberStartsAtOne() throws IOException {
        final String csv = "a,b\n1,2\n3,4";
        try (CSVParser parser = CSVParser.parse(csv, CSVFormat.DEFAULT)) {
            assertEquals(0L, parser.getRecordNumber());
            parser.nextRecord();
            assertEquals(1L, parser.getRecordNumber());
            parser.nextRecord();
            assertEquals(2L, parser.getRecordNumber());
        }
    }

    @Test
    public void testBuilderRecordNumberOffset() throws IOException {
        final String csv = "a,b\n1,2";
        try (CSVParser parser = CSVParser.builder()
                .setReader(new StringReader(csv))
                .setFormat(CSVFormat.DEFAULT)
                .setRecordNumber(10)
                .get()) {
            assertEquals(9L, parser.getRecordNumber());
            parser.nextRecord();
            assertEquals(10L, parser.getRecordNumber());
        }
    }
