    @Test
    public void testMultipleParsersOnSameReader() throws IOException {
        final String csv = "a,b\n1,2\n3,4";
        try (Reader reader = new StringReader(csv)) {
            try (CSVParser parser1 = CSVParser.parse(reader, CSVFormat.DEFAULT)) {
                final List<CSVRecord> records1 = parser1.getRecords();
                assertEquals(2, records1.size());
            }
            // Reader is consumed, second parser gets nothing
            try (CSVParser parser2 = CSVParser.parse(reader, CSVFormat.DEFAULT)) {
                final List<CSVRecord> records2 = parser2.getRecords();
                assertTrue(records2.isEmpty());
            }
