    @Test
    public void testIterator() throws IOException {
        final String csv = "a,b,c\n1,2,3\n4,5,6";
        try (CSVParser parser = CSVParser.parse(csv, CSVFormat.DEFAULT)) {
            final Iterator<CSVRecord> iterator = parser.iterator();
            assertTrue(iterator.hasNext());
            final CSVRecord record1 = iterator.next();
            assertArrayEquals(new String[]{"1", "2", "3"}, record1.values());
            assertTrue(iterator.hasNext());
            final CSVRecord record2 = iterator.next();
            assertArrayEquals(new String[]{"4", "5", "6"}, record2.values());
            assertFalse(iterator.hasNext());
        }
    }

