public class CSVPrinterTest {

    private StringWriter stringWriter;
    private CSVFormat format;

    @Before
    public void setUp() {
        stringWriter = new StringWriter();
        format = CSVFormat.DEFAULT;
    }

    @Test
    public void testConstructorNullAppendableThrowsNullPointerException() {
        try {
            new CSVPrinter(null, format);
            fail("Expected NullPointerException");
        } catch (NullPointerException e) {
            assertEquals("appendable", e.getMessage());
        } catch (IOException e) {
            fail("Unexpected IOException: " + e.getMessage());
        }
    }

    @Test
    public void testConstructorNullFormatThrowsNullPointerException() {
        try {
            new CSVPrinter(stringWriter, null);
            fail("Expected NullPointerException");
        } catch (NullPointerException e) {
            assertEquals("format", e.getMessage());
        } catch (IOException e) {
            fail("Unexpected IOException: " + e.getMessage());
        }
    }

    @Test
    public void testConstructorWithHeaderComments() throws IOException {
        CSVFormat formatWithComments = CSVFormat.DEFAULT
            .withHeaderComments("Comment line 1", "Comment line 2");

        try (CSVPrinter printer = new CSVPrinter(stringWriter, formatWithComments)) {
            // Header comments should be printed during construction
        }

        String output = stringWriter.toString();
        assertTrue(output.contains("# Comment line 1"));
        assertTrue(output.contains("# Comment line 2"));
    }

    @Test
    public void testConstructorWithHeader() throws IOException {
        CSVFormat formatWithHeader = CSVFormat.DEFAULT.withHeader("col1", "col2", "col3");

        try (CSVPrinter printer = new CSVPrinter(stringWriter, formatWithHeader)) {
            // Header should be printed during construction
        }

        String output = stringWriter.toString();
        assertTrue(output.contains("col1,col2,col3"));
    }

    @Test
    public void testConstructorWithHeaderAndSkipHeaderRecord() throws IOException {
        CSVFormat formatWithHeader = CSVFormat.DEFAULT
            .withHeader("col1", "col2")
            .withSkipHeaderRecord(true);

        try (CSVPrinter printer = new CSVPrinter(stringWriter, formatWithHeader)) {
            // Header should NOT be printed during construction
        }

        String output = stringWriter.toString();
        assertEquals("", output);
    }

