    // Simple ResultSet implementation for testing without Mockito
    private static class TestResultSet implements ResultSet {
        private final String[] columnLabels;
        private int currentRow = -1;
        private final Object[][] data;

        TestResultSet(String[] columnLabels) {
            this.columnLabels = columnLabels;
            this.data = new Object[0][];
        }

        TestResultSet(String[] columnLabels, Object[][] data) {
            this.columnLabels = columnLabels;
            this.data = data;
        }

        @Override
        public ResultSetMetaData getMetaData() throws SQLException {
            return new TestResultSetMetaData(columnLabels);
        }

        @Override
        public boolean next() throws SQLException {
            currentRow++;
            return currentRow < data.length;
        }

        @Override
        public Object getObject(int columnIndex) throws SQLException {
            if (currentRow >= 0 && currentRow < data.length && columnIndex > 0 && columnIndex <= data[currentRow].length) {
                return data[currentRow][columnIndex - 1];
            }
            return null;
        }

        // Unused methods - minimal implementations to satisfy ResultSet interface
        @Override public boolean wasNull() throws SQLException { return false; }
        @Override public String getString(int columnIndex) throws SQLException { return null; }
        @Override public boolean getBoolean(int columnIndex) throws SQLException { return false; }
        @Override public byte getByte(int columnIndex) throws SQLException { return 0; }
